def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression with +, -, *, /, parentheses, and 
    floating-point numbers using the Shunting Yard algorithm to convert 
    the infix expression to postfix notation, followed by evaluation of 
    the postfix expression.
    """

    def shunting_yard(expression):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        operators = []
        i = 0
        n = len(expression)

        while i < n:
            if expression[i].isspace():
                i += 1
                continue
            if expression[i].isdigit() or expression[i] == '.':
                number = ''
                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    number += expression[i]
                    i += 1
                output.append(float(number))
                continue
            if expression[i] in precedence:
                while (operators and operators[-1] != '(' and
                       precedence[operators[-1]] >= precedence[expression[i]]):
                    output.append(operators.pop())
                operators.append(expression[i])
            elif expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # popping the '('
            i += 1

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    postfix_expr = shunting_yard(expr)
    return evaluate_postfix(postfix_expr)

