    """
    Evaluates an arithmetic expression with +, -, *, /, parentheses, and 
    floating-point numbers using the Shunting-yard algorithm and reverse 
    Polish notation for evaluation.
    """
    def shunting_yard(expression):
        output = []
        operators = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        for token in tokenize(expression):
            if token.isnumeric() or '.' in token:
                output.append(float(token))
            elif token in precedence:
                while (operators and operators[-1] != '(' and
                       precedence[token] <= precedence[operators[-1]]):
                    output.append(operators.pop())
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # Remove '('
        while operators:
            output.append(operators.pop())
        return output

    def tokenize(expression):
        number = ''
        for char in expression:
            if char.isdigit() or char == '.':
                number += char
            else:
                if number:
                    yield number
                    number = ''
                if char in "+-*/()":
                    yield char
        if number:
            yield number

    def rpn_eval(rpn):
        stack = []
        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b, a = stack.pop(), stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    rpn = shunting_yard(expr)
    return rpn_eval(rpn)

