def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression with +, -, *, /, parentheses, and 
    floating-point numbers using the Shunting Yard algorithm for parsing
    and evaluating the expression in a stack-based manner.
    """
    def precede(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(left / right)

    def tokenize(expression):
        tokens = []
        number = ''
        for char in expression:
            if char in '0123456789.':
                number += char
            else:
                if number:
                    tokens.append(float(number))
                    number = ''
                if char in '+-*/()':
                    tokens.append(char)
        if number:
            tokens.append(float(number))
        return tokens

    def evaluate_expression(expression):
        tokens = tokenize(expression)
        values = []
        operators = []

        for token in tokens:
            if isinstance(token, float):
                values.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Pop the '('
            else:  # Operator
                while (operators and
                       precede(operators[-1]) >= precede(token)):
                    apply_operator(operators, values)
                operators.append(token)

        while operators:
            apply_operator(operators, values)

        return values[0]

    return evaluate_expression(expr)

